#include "csapp.h"
void mmapcopy(int fd, int size)
{
    /* Ptr to memory mapped area */
    char *bufp;
    bufp = Mmap(NULL, size, 
                PROT_READ,
                MAP_PRIVATE, 
                fd, 0);
    Write(1, bufp, size);
    return;
}

